head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isRun = true;
scwin.isAuto = true;
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
    > X 오류 확인 - 기존 소스 확인 필요

*/

scwin.checkedAlarm;
scwin.firstDate;
scwin.lastDate;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 페이지 로드 이벤트 핸들러(현재 별도 초기화 로직 없음).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 시 호출되는 페이지 언로드 이벤트 핸들러(현재 별도 정리 로직 없음).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MxDataSet_OnLoadCompleted
 * @description MxDataSet 조회 완료 콜백 — 조회 결과 총 건수를 textbox_1에 표시하고 알람 대상 데이터를 점검한다(checkData).
 * @param {Object} e 서브미션 완료 이벤트/결과 객체
 * @returns {void}
 * @hidden N
 * @example scwin.MxDataSet_OnLoadCompleted(e);
 */
scwin.MxDataSet_OnLoadCompleted = function(e) {
    try {
        textbox_1.setValue("총 " + rowcount + "건");
        scwin.checkData();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80220.MxDataSet_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name MxGrid_1_onheadcheckclick
 * @description 그리드 헤더 체크박스 클릭 — 헤더 체크 상태에 따라 전체 행의 선택(CHK_FLAG) 값을 일괄 설정한다(col·bCheck는 W-Craft 이관 잔존 — 원본 소스 확인 필요).
 * @param {String} headerId 클릭한 헤더 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.MxGrid_1_onheadcheckclick(headerId);
 */
scwin.MxGrid_1_onheadcheckclick = function(headerId) {
    try {
        let check = 0;
        if (col === 0) {
            if (bCheck === 1) check = 1;
            for (let i = 0; i < MxDataSet.getRowCount(); i++) {
                MxDataSet.setCellData(i, "CHK_FLAG", check);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80220.MxGrid_1_onheadcheckclick" });
    }
};

/**
 * @method
 * @name btn_cal_onclick
 * @description [달력] 버튼 클릭 — 수신일자 입력(txb_date)용 달력 팝업(popUpCalendar)을 연다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_cal_onclick(e);
 */
scwin.btn_cal_onclick = function(e) {
    try {
        popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80220.btn_cal_onclick" });
    }
};

/**
 * @method
 * @name btn_sys_search_onclick
 * @description [조회] 버튼 클릭 — 수신일자(txb_date) 입력 여부를 확인한 후 자동 갱신을 중지하고(stopReload) 수동 조회 모드로 목록을 다시 조회한다(listSyncAuto).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_sys_search_onclick(e);
 */
scwin.btn_sys_search_onclick = function(e) {
    try {
        if (txb_date.Text !== "") {

            scwin.stopReload();
            scwin.isAuto = false;
            scwin.listSyncAuto();
        } else {
            alert("일자를 지정하십시요");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80220.btn_sys_search_onclick" });
    }
};

/**
 * @method
 * @name btn_toExcel_onclick
 * @description [엑셀다운로드] 버튼 클릭 — 그리드(MxGrid_1) 데이터를 '코스닥매매시스템전문수신로그' 엑셀 파일로 내려받는다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_toExcel_onclick(e);
 */
scwin.btn_toExcel_onclick = function(e) {
    try {
        $c.data.downloadGridViewExcel(MxGrid_1, {fileName: "코스닥매매시스템전문수신로그", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80220.btn_toExcel_onclick" });
    }
};

/**
 * @method
 * @name btnStop_onclick
 * @description [체크항목알람정지] 버튼 클릭 — 선택 항목의 알람을 정지한다(stopNotice).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btnStop_onclick(e);
 */
scwin.btnStop_onclick = function(e) {
    try {
        scwin.stopNotice();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80220.btnStop_onclick" });
    }
};

/**
 * @method
 * @name button_1_onclick
 * @description [자동반복멈춤] 버튼 클릭 — 자동 반복 조회를 중지한다(stopReload).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.button_1_onclick(e);
 */
scwin.button_1_onclick = function(e) {
    try {
        scwin.stopReload();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80220.button_1_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 목록 조회 서브미션 — 자동 갱신 모드(isAuto=true)로 /kosdaqtrdlog.do 를 호출해 MxDataSet을 갱신하고 마지막 비교 시간을 표시한다(setNowTime). (원주석: true:자동refres, true:날짜 변경등으로 인한 수동 조회.)
 * @returns {Promise<void>}
 * @hidden N
 * @example scwin.listSync();
 */
scwin.listSync = async function() {
    scwin.isAuto = true;
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/kosdaqtrdlog.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_OnLoadCompleted(sbmRtn); // 구 콜백 연결

    scwin.setNowTime();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkData
 * @description 조회 결과의 알람 플래그를 재설정(setAlarmPlag)한 뒤 알람 대상 여부를 점검한다(checkAlarm).
 * @returns {void}
 * @hidden N
 * @example scwin.checkData();
 */
scwin.checkData = function() {
    if (scwin.setAlarmPlag()) scwin.checkAlarm();
};

/**
 * @method
 * @name checkAlarm
 * @description 미확인(CHK_FLAG=0) 행이 있으면 경고음 재생(playNotice)을 예약한다.
 * @returns {void}
 * @hidden N
 * @example scwin.checkAlarm();
 */
scwin.checkAlarm = function() {
    let tmpChk;
    for (let i = 0; i < MxDataSet.getRowCount(); i++) {
        tmpChk = MxDataSet.getCellData(i, "CHK_FLAG");

        if (tmpChk === 0) setTimeout('playNotice()', 1000);
    }
};

/**
 * @method
 * @name setAlarmPlag
 * @description 알람 정지 처리된 행 목록(checkedAlarm)과 대조해 해당 행의 선택(CHK_FLAG) 값을 재설정한다(W-Craft X 변환 구문 — 원본 소스 확인 필요).
 * @returns {Boolean} 항상 true
 * @hidden N
 * @example if (scwin.setAlarmPlag()) scwin.checkAlarm();
 */
scwin.setAlarmPlag = function() {
    let idx = 0;
    if (scwin.checkedAlarm) {
        for (let i = 0; i < scwin.checkedAlarm.length; i++) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            idx = MxDataSet.NameValueRow("ROW_ID", scwin.checkedAlarm[i]);
            if (idx !== 0) /*ORG SRC: if (idx != 0) MxDataSet.NameValue(idx, "CHK_FLAG") = 1;*/ X = 1;
        }
    }
    return true;
};

/**
 * @method
 * @name playNotice
 * @description 경고음(alertWave)을 재생한다.
 * @returns {void}
 * @hidden N
 * @example scwin.playNotice();
 */
scwin.playNotice = function() {

    alertWave.play();
};

/**
 * @method
 * @name stopNotice
 * @description 선택(CHK_FLAG=1)된 행의 ROW_ID를 checkedAlarm 목록에 보관하고 경고음을 정지한 뒤 자동 조회를 재시작한다. 선택 항목이 없으면 안내 메시지를 표시한다.
 * @returns {void}
 * @hidden N
 * @example scwin.stopNotice();
 */
scwin.stopNotice = function() {
    scwin.isAuto = false;
    let tmpRowID;
    let tmpChkVal;
    let chkCnt = 0;
    scwin.checkedAlarm = new Array();
    if (MxDataSet.getRowCount() !== 0) {
        for (let i = 0; i < MxDataSet.getRowCount(); i++) {
            tmpChkVal = MxDataSet.getCellData(i, "CHK_FLAG");
            if (tmpChkVal === 1) {
                scwin.checkedAlarm[chkCnt] = MxDataSet.getCellData(i, "ROW_ID");
                chkCnt++;
            }
        }
        if (chkCnt === 0) {
            alert('정지할 항목을 선택하세요.');
        } else {

            alertWave.stop();

            scwin.stopReload();
            scwin.listSyncAuto();
        }
    } else {
        alert('정지할 항목을 선택하세요.');
    }
};

/**
 * @method
 * @name setWave
 * @description 경고음 재생용 embed(alertWave)를 panelWav에 생성한다.
 * @returns {void}
 * @hidden N
 * @example scwin.setWave();
 */
scwin.setWave = function() {

    panelWav.style.display = 'none';
    panelWav.innerHTML = "<embed src='/sysmonitor/alert_elw.wav' name='alertWave' autostart='false' loop='true'>";
};

/**
 * @method
 * @name setNowTime
 * @description 현재 시각(시:분:초)을 마지막 비교 시간(txtNowDate)에 표시한다.
 * @returns {void}
 * @hidden N
 * @example scwin.setNowTime();
 */
scwin.setNowTime = function() {
    const now = new Date();
    const hours = now.getHours();
    const mins = now.getMinutes();
    const secs = now.getSeconds();
    txtNowDate.setValue(hours + ":" + mins + ":" + secs);
};

/**
 * @method
 * @name getYYYYMMDD
 * @description 현재 일자를 YYYYMMDD 형식 문자열로 만들어 반환한다.
 * @returns {String} YYYYMMDD 형식 일자 문자열
 * @hidden N
 * @example const today = scwin.getYYYYMMDD();
 */
scwin.getYYYYMMDD = function() {
    const now = new Date();
    let month = (now.getMonth() + 1) + "";
    let day = now.getDate() + "";
    if (day.length === 1) day = "0" + day;
    if (month.length === 1) month = "0" + month;
    return now.getYear() + "" + month + "" + day;
};

/**
 * @method
 * @name listSyncAuto
 * @description 1분 주기 자동 재조회 타이머(setInterval)를 시작하고 안내 문구 갱신(setAlertTxt) 후 즉시 1회 조회한다(reLoadData). (원주석: ver:0 자동 ver:1 수동 조회버튼을 눌렀을경우 날짜를 갖고 넘어 가야함.)
 * @returns {void}
 * @hidden N
 * @example scwin.listSyncAuto();
 */
scwin.listSyncAuto = function() {

    threadID = setInterval('reLoadData()', 60000);
    scwin.isRun = true;
    scwin.setAlertTxt();
    scwin.reLoadData();
};

/**
 * @method
 * @name reLoadData
 * @description 자동 조회 모드면 수신일자를 오늘 일자로 갱신하고, 일자가 바뀐 경우 선택 목록(checkedAlarm) 초기화·경고음 정지 후 목록을 재조회한다(listSync).
 * @returns {void}
 * @hidden N
 * @example scwin.reLoadData();
 */
scwin.reLoadData = function() {
    if (scwin.isAuto) txb_date.setValue(scwin.getYYYYMMDD());
    scwin.lastDate = txb_date.text;
    if (scwin.firstDate !== scwin.lastDate) {
        // 날짜를 변경하면 선택한 리스트도 초기화 시켜준다.			
        scwin.checkedAlarm = new Array();
        scwin.firstDate = txb_date.text;

        alertWave.stop();
    }
    if (scwin.isClearData()) scwin.listSync();
};

/**
 * @method
 * @name setAlertTxt
 * @description 자동 reload 실행/중지 상태 안내 문구(txtAlert)를 갱신한다.
 * @returns {void}
 * @hidden N
 * @example scwin.setAlertTxt();
 */
scwin.setAlertTxt = function() {
    if (scwin.isRun) txtAlert.setValue("1분 마다 reload 되고 있습니다.");

    else txtAlert.setValue("reload 중지되었습니다.");
};

/**
 * @method
 * @name isClearData
 * @description 기준일자(txb_date) 입력 여부를 확인하고, 입력된 경우 MxDataSet을 비운 뒤 true를 반환한다.
 * @returns {Boolean} 조회 진행 가능 여부
 * @hidden N
 * @example if (scwin.isClearData()) scwin.listSync();
 */
scwin.isClearData = function() {
    if (txb_date.Text !== "") {
        MxDataSet.setJSON([]);
        return true;
    } else {
        alert("기준일자를 지정하십시요");
        return false;
    }
};

/**
 * @method
 * @name stopReload
 * @description 자동 재조회 타이머를 정지하고 상태 안내 문구를 갱신한다(setAlertTxt).
 * @returns {void}
 * @hidden N
 * @example scwin.stopReload();
 */
scwin.stopReload = function() {

    clearInterval(threadID);
    scwin.isRun = false;
    scwin.setAlertTxt();
};

/**
 * @method
 * @name MxGrid_1_CanColumnPosChange
 * @description 그리드 컬럼 이동 허용 여부 콜백 — 항상 허용한다.
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 id
 * @returns {Boolean} 항상 true
 * @hidden N
 * @example scwin.MxGrid_1_CanColumnPosChange(0, "h_ACPT_NO");
 */
scwin.MxGrid_1_CanColumnPosChange = function(row, colid) {
    return true;
};

/**
 * @method
 * @name gform_onload
 * @description 구 Gauce gform onload 이관 함수 — 목록 초기 조회 후 오늘 일자·기준일자(firstDate)를 설정하고 경고음 embed 생성(setWave)과 자동 재조회 시작(listSyncAuto)을 수행한다.
 * @returns {Promise<void>}
 * @hidden N
 * @example scwin.gform_onload();
 */
scwin.gform_onload = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_OnLoadCompleted(sbmRtn); // 구 콜백 연결

    toDaySet(txb_date); // firstDate를 셋팅하기 위해 첨에 한번하고  auto refresh될때 내일로 넘어갔는지 체크하기 위해  fn_list_sync_auto()에서 한번더 한다.
    scwin.firstDate = txb_date.text;
    scwin.setWave();
    scwin.listSyncAuto();
};
